// @FIGURE_CODE_BEGIN
/* ── Element spec (build exactly this) ───────────────────────────────────────
   glass wall        -> CylinderGeometry(1.2,1.2,3.0,64,1,true)  MeshPhysicalMaterial #dff0f2 op .16 depthWrite false
   glass bottom      -> CircleGeometry(1.2,64) rotX -90 @ y=-1.5  #dff0f2 op .35
   left highlight    -> CylinderGeometry(1.19,1.19,2.7, 24,1,true, thetaStart, thetaLen) white op .22
   rim lip           -> TorusGeometry(1.22,0.10,16,64) rotX -90 @ y=+1.5  #e8f2f5 opaque
   rim top ring      -> RingGeometry(1.12,1.22,64) rotX -90 @ y=+1.5  #f2f9fb
   liquid column     -> CylinderGeometry(1.15,1.15,2.23,64) center y=-0.365  #c5d8ee op .55 depthWrite false
   free surface disc -> CircleGeometry(1.15,64) rotX -90 @ y=+0.752  #b6cbe6
   surface band      -> RingGeometry(1.06,1.15,64) rotX -90 @ y=+0.755  #9fb8d8
   bottom pool       -> CircleGeometry(1.14,64) rotX -90 @ y=-1.44  #9dbcdc op .9
   sample cubes 1-3  -> BoxGeometry(1,1,1): LineSegments(EdgesGeometry, LineDashedMaterial #1a1a1a)
                        + translucent amber fill Mesh (opacity 0 unless selected)
   numerals 1,2,3    -> addLabel HTML glyph at cube centre
   3 curved arrows   -> TubeGeometry(QuadraticBezierCurve3, r=0.016) + ConeGeometry(0.055,0.16) head, black
   3 math labels     -> addLabel tall-parenthesis (Δm/ΔV)_n, serif italic
   lights            -> HemisphereLight + DirectionalLight key
──────────────────────────────────────────────────────────────────────────── */

document.getElementById('btnReset').style.display = '';

/* ── Lights ───────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xccd8e4, 1.05));
const key = new THREE.DirectionalLight(0xffffff, 0.55);
key.position.set(2.5, 4, 3);
scene.add(key);
scene.add(new THREE.AmbientLight(0xffffff, 0.35));

const C = {
  glass: 0xdff0f2, rim: 0xe8f2f5, rimTop: 0xf2f9fb,
  liquid: 0xc5d8ee, surf: 0xb6cbe6, band: 0x9fb8d8, pool: 0x9dbcdc,
  ink: 0x1a1a1a, sel: 0xc2410c, amber: 0xffb703
};

/* ── Liquid (drawn first so the wall sorts over it) ──────────────────────── */
const liquidTop = 0.75, liquidBot = -1.48;
const liquid = new THREE.Mesh(
  new THREE.CylinderGeometry(1.15, 1.15, liquidTop - liquidBot, 64, 1, true),
