    metalness: 0.0, side: THREE.DoubleSide, depthWrite: false
  })
);
liquid.position.y = (liquidTop + liquidBot) / 2;
liquid.renderOrder = 1;
scene.add(liquid);
registerInteractive(liquid, {
  title: 'Liquid column',
  tooltip: 'The liquid body',
  body: 'Density is not a property of this whole column. It is defined at each point as the limit of Δm/ΔV for a small volume surrounding that point.'
});

const pool = new THREE.Mesh(
  new THREE.CircleGeometry(1.14, 64),
  new THREE.MeshBasicMaterial({ color: C.pool, transparent: true, opacity: 0.9, side: THREE.DoubleSide })
);
pool.rotation.x = -Math.PI / 2; pool.position.y = -1.44; pool.renderOrder = 1;
scene.add(pool);

const surf = new THREE.Mesh(
  new THREE.CircleGeometry(1.15, 64),
  new THREE.MeshBasicMaterial({ color: C.surf, transparent: true, opacity: 0.92, side: THREE.DoubleSide })
);
surf.rotation.x = -Math.PI / 2; surf.position.y = liquidTop + 0.002; surf.renderOrder = 2;
scene.add(surf);

const band = new THREE.Mesh(
  new THREE.RingGeometry(1.06, 1.15, 64),
  new THREE.MeshBasicMaterial({ color: C.band, transparent: true, opacity: 0.95, side: THREE.DoubleSide })
);
band.rotation.x = -Math.PI / 2; band.position.y = liquidTop + 0.005; band.renderOrder = 3;
scene.add(band);
registerInteractive(band, {
  title: 'Free surface',
  tooltip: 'Liquid free surface',
  body: 'The liquid fills the lower part of the vessel; the sample cubes all lie beneath this surface.'
});

/* ── Glass container ─────────────────────────────────────────────────────── */
const wall = new THREE.Mesh(
  new THREE.CylinderGeometry(1.2, 1.2, 3.0, 64, 1, true),
  new THREE.MeshPhysicalMaterial({
    color: C.glass, transparent: true, opacity: 0.16, roughness: 0.08,
    metalness: 0.0, side: THREE.DoubleSide, depthWrite: false
  })
);
wall.renderOrder = 4;
scene.add(wall);
registerInteractive(wall, {
  title: 'Container',
  tooltip: 'Glass vessel',
  body: 'A clear cylinder, radius 1.2 and height 3.0 in figure units (1 unit = 10 cm), open at the top.'
});

const glassBottom = new THREE.Mesh(
  new THREE.CircleGeometry(1.2, 64),
  new THREE.MeshPhysicalMaterial({
    color: C.glass, transparent: true, opacity: 0.35, roughness: 0.15,
