  })
);
glassBottom.rotation.x = -Math.PI / 2; glassBottom.position.y = -1.5; glassBottom.renderOrder = 4;
scene.add(glassBottom);

// faint lighter vertical highlight on the left wall
const highlight = new THREE.Mesh(
  new THREE.CylinderGeometry(1.185, 1.185, 2.7, 24, 1, true, Math.PI * 0.62, 0.16),
  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false })
);
highlight.position.y = 0.0; highlight.renderOrder = 5;
scene.add(highlight);

const rim = new THREE.Mesh(
  new THREE.TorusGeometry(1.22, 0.10, 16, 72),
