);
rim.rotation.x = -Math.PI / 2; rim.position.y = 1.5; rim.renderOrder = 6;
scene.add(rim);

const rimTop = new THREE.Mesh(
  new THREE.RingGeometry(1.12, 1.22, 72),
  new THREE.MeshBasicMaterial({ color: C.rimTop, side: THREE.DoubleSide, transparent: true, opacity: 0.95 })
);
rimTop.rotation.x = -Math.PI / 2; rimTop.position.y = 1.5; rimTop.renderOrder = 6;
scene.add(rimTop);
registerInteractive(rim, {
  title: 'Rounded glass lip',
  tooltip: 'Rim of the vessel',
  body: 'The thick rolled rim marks the top of the container; the liquid surface sits about a quarter of the height below it.'
});

/* ── Sample cubes ────────────────────────────────────────────────────────── */
const MAX_EDGE = 0.85;
