const edgeGeo = new THREE.EdgesGeometry(cubeGeo);

const cubeDefs = [
  { n: 1, pos: [-0.42, 0.18, 0.25] },
  { n: 2, pos: [0.30, -0.28, 0.10] },
  { n: 3, pos: [-0.05, -1.05, 0.15] }
];
const cubes = [];

cubeDefs.forEach(def => {
  const g = new THREE.Group();
  g.position.set(def.pos[0], def.pos[1], def.pos[2]);

  const fill = new THREE.Mesh(cubeGeo, new THREE.MeshBasicMaterial({
