/* ── State + controls ────────────────────────────────────────────────────── */
let selected = 1;
let model = 'Uniform';
let relSize = 0.5;

const szInput = document.getElementById('sampleSize');
const szVal = document.getElementById('szVal');
const readout = document.getElementById('readout');
const narration = document.getElementById('narration');
const btnCube = { 1: document.getElementById('btnCube1'), 2: document.getElementById('btnCube2'), 3: document.getElementById('btnCube3') };
const btnUni = document.getElementById('btnUniform');
const btnHet = document.getElementById('btnHetero');

function rho(y) { return model === 'Uniform' ? 1000 : 1000 + 55 * (0.75 - y); }

function applySize() {
  const edge = relSize * MAX_EDGE;
  cubes.forEach(c => {
    c.group.scale.setScalar(edge);
    // keep the dash pattern a constant world size despite the group scale
    const ds = 0.075 / edge, gs = 0.055 / edge;
    c.mat.dashSize = ds; c.mat.gapSize = gs;
    c.matB.dashSize = ds; c.matB.gapSize = gs;
    c.mat.needsUpdate = true; c.matB.needsUpdate = true;
  });
}

function applySelection() {
  cubes.forEach(c => {
    const on = c.n === selected;
    c.fill.material.opacity = on ? 0.22 : 0.0;
    c.mat.color.setHex(on ? C.sel : C.ink);
    c.matB.opacity = on ? 1.0 : 0.0;
    c.label.div.style.fontWeight = on ? 'bold' : 'normal';
    c.label.div.style.color = on ? '#a33500' : '#111';
  });
  for (const k in btnCube) btnCube[k].classList.toggle('active', Number(k) === selected);
}

function fmt(v, digits) { return v.toLocaleString(undefined, { minimumFractionDigits: digits, maximumFractionDigits: digits }); }

function updateReadout() {
  const edge = relSize * MAX_EDGE;          // world units
  const cm = edge * 10;                     // 1 world unit = 10 cm
  const V_cm3 = cm * cm * cm;
  const rows = cubes.map(c => {
    const r = rho(c.y);
    const m_g = r * V_cm3 * 1e-6 * 1000;    // kg/m^3 * m^3 -> kg -> g
    const on = c.n === selected;
    return `<div style="display:flex;justify-content:space-between;gap:6px;padding:1px 0;
              ${on ? 'background:#fff3e0;font-weight:bold;' : 'color:#555;'}">
              <span>(&Delta;m/&Delta;V)<sub>${c.n}</sub></span>
              <span>${fmt(r, 0)} kg/m³</span></div>`;
  }).join('');
  const rSel = rho(cubes.find(c => c.n === selected).y);
  const m_g = rSel * V_cm3 * 1e-6 * 1000;
  readout.innerHTML =
    `<div style="font-weight:bold;margin-bottom:3px">Cube ${selected} &nbsp;(${model})</div>` +
    `<div>&Delta;V = ${V_cm3.toPrecision(3)} cm³ &nbsp;(edge ${cm.toFixed(2)} cm)</div>` +
    `<div>&Delta;m = ${m_g.toPrecision(3)} g</div>` +
    `<div style="margin:3px 0 4px 0;border-top:1px solid #e3e6ea;padding-top:3px">
       &Delta;m/&Delta;V = <b>${fmt(rSel, 0)} kg/m³</b></div>` + rows;
}

function refresh() { applySize(); applySelection(); updateReadout(); }

function selectCube(n) { selected = n; refresh(); }
function setModel(m) {
  model = m;
