}

[1, 2, 3].forEach(n => btnCube[n].addEventListener('click', () => { stopPlay(); selectCube(n); }));
btnUni.addEventListener('click', () => { stopPlay(); setModel('Uniform'); });
btnHet.addEventListener('click', () => { stopPlay(); setModel('Heterogeneous'); });
szInput.addEventListener('input', () => { stopPlay(); cancelTween(); setSize(parseFloat(szInput.value), true); });

/* ── Guided demo ─────────────────────────────────────────────────────────── */
const steps = [
  {
    title: '1. One bulk density', select: 1, model: 'Uniform', size: 0.5,
    text: 'In a uniform liquid, each dashed cube returns the same Δm/ΔV. One number describes the whole vessel.'
  },
  {
    title: '2. Sample cube 3 near the bottom', select: 3, model: 'Heterogeneous', size: 0.5,
    text: 'Switch the fluid to heterogeneous: the deepest cube now measures a larger mass in the same volume, so (Δm/ΔV)₃ exceeds the others.'
  },
  {
    title: '3. Shrink the sampling volume', select: 3, model: 'Heterogeneous', size: 0.15,
    text: 'Δm and ΔV both collapse toward zero, yet their ratio stabilises — this limiting value is the local density at that point.'
  },
  {
    title: '4. Compare all three points', select: 2, model: 'Heterogeneous', size: 0.5,
    text: 'Back at full size, the three subscripted ratios are distinct numbers tied to three positions: density is defined point by point, not for the container as a whole.'
  }
];
let stepIdx = 0, tweenId = null, playTimer = null;

function cancelTween() { if (tweenId) { cancelAnimationFrame(tweenId); tweenId = null; } }

function tweenSize(target, ms) {
  cancelTween();
  const from = relSize, t0 = performance.now();
  (function run(now) {
    const k = Math.min(1, ((now || t0) - t0) / ms);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    setSize(from + (target - from) * e);
    if (k < 1) tweenId = requestAnimationFrame(run); else tweenId = null;
  })(t0);
}

function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  setModel(s.model);
  selectCube(s.select);
  tweenSize(s.size, 700);
  narration.innerHTML = `<b>${s.title}</b><br>${s.text}`;
}

document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 3600);
});

/* ── Init ────────────────────────────────────────────────────────────────── */
