/* ── Curved arrows (quadratic Bézier tube + cone head) ───────────────────── */
function curvedArrow(p0, p1, p2) {
  const curve = new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(...p0), new THREE.Vector3(...p1), new THREE.Vector3(...p2));
  const m = new THREE.MeshBasicMaterial({ color: 0x111111 });
  const grp = new THREE.Group();
  grp.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 64, 0.016, 8, false), m));
  const end = curve.getPoint(1);
  const tan = curve.getTangent(1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.17, 18), m);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  head.position.copy(end).addScaledVector(tan, 0.07);
  grp.add(head);
  grp.renderOrder = 10;
  scene.add(grp);
  return grp;
}

// 1: comes in from the RIGHT, sweeping below the free-surface ellipse
curvedArrow([1.72, 0.66, 0.50], [0.86, 0.34, 0.44], [-0.08, 0.19, 0.30]);
// 2: runs left into cube 2's right face
