/* ── Math labels ─────────────────────────────────────────────────────────── */
function fracLabel(sub) {
  return `<span style="display:inline-flex;align-items:center;font-family:Georgia,'Times New Roman',serif;">
    <span style="font-size:30px;line-height:0.9">(</span>
    <span style="display:inline-flex;flex-direction:column;align-items:center;line-height:1.15;padding:0 3px;font-size:14px;font-style:italic">
      <span>&Delta;m</span>
      <span style="border-top:1.2px solid #111;padding-top:1px">&Delta;V</span>
    </span>
    <span style="font-size:30px;line-height:0.9">)</span>
    <sub style="font-size:11px">${sub}</sub></span>`;
}
addLabel(fracLabel(1), new THREE.Vector3(2.16, 0.80, 0.50));
addLabel(fracLabel(2), new THREE.Vector3(2.28, -0.40, 0.40));
addLabel(fracLabel(3), new THREE.Vector3(-2.36, -0.58, 0.46));

/* ── State + controls ────────────────────────────────────────────────────── */
let selected = 1;
let model = 'Uniform';
let relSize = 0.5;

const szInput = document.getElementById('sampleSize');
const szVal = document.getElementById('szVal');
const readout = document.getElementById('readout');
const narration = document.getElementById('narration');
const btnCube = { 1: document.getElementById('btnCube1'), 2: document.getElementById('btnCube2'), 3: document.getElementById('btnCube3') };
const btnUni = document.getElementById('btnUniform');
const btnHet = document.getElementById('btnHetero');

function rho(y) { return model === 'Uniform' ? 1000 : 1000 + 55 * (0.75 - y); }

function applySize() {
  const edge = relSize * MAX_EDGE;
  cubes.forEach(c => {
    c.group.scale.setScalar(edge);
    // keep the dash pattern a constant world size despite the group scale
    const ds = 0.075 / edge, gs = 0.055 / edge;
    c.mat.dashSize = ds; c.mat.gapSize = gs;
    c.matB.dashSize = ds; c.matB.gapSize = gs;
    c.mat.needsUpdate = true; c.matB.needsUpdate = true;
  });
}

function applySelection() {
  cubes.forEach(c => {
    const on = c.n === selected;
    // soft, outline-first highlight: default state stays plain black dashes
    c.fill.material.opacity = on ? 0.10 : 0.0;
    c.matB.opacity = on ? 0.95 : 0.0;
    c.label.div.style.fontWeight = 'bold';
    c.label.div.style.fontSize = on ? '20px' : '18px';
    c.label.div.style.color = '#111';
  });
  for (const k in btnCube) btnCube[k].classList.toggle('active', Number(k) === selected);
}

function fmt(v, digits) { return v.toLocaleString(undefined, { minimumFractionDigits: digits, maximumFractionDigits: digits }); }

function updateReadout() {
  const edge = relSize * MAX_EDGE;          // world units
  const cm = edge * 10;                     // 1 world unit = 10 cm
  const V_cm3 = cm * cm * cm;
  const rows = cubes.map(c => {
    const r = rho(c.y);
    const on = c.n === selected;
    return `<div style="display:flex;justify-content:space-between;gap:6px;padding:1px 0;
              ${on ? 'background:#f1f6fb;font-weight:bold;' : 'color:#555;'}">
              <span>(&Delta;m/&Delta;V)<sub>${c.n}</sub></span>
              <span>${fmt(r, 0)} kg/m³</span></div>`;
  }).join('');
  const rSel = rho(cubes.find(c => c.n === selected).y);
  const m_g = rSel * V_cm3 * 1e-6 * 1000;   // kg/m^3 · m^3 → kg → g
  readout.innerHTML =
    `<div style="font-weight:bold;margin-bottom:3px">Cube ${selected} &nbsp;(${model})</div>` +
    `<div>&Delta;V = ${V_cm3.toPrecision(3)} cm³ &nbsp;(edge ${cm.toFixed(2)} cm)</div>` +
    `<div>&Delta;m = ${m_g.toPrecision(3)} g</div>` +
    `<div style="margin:3px 0 4px 0;border-top:1px solid #e3e6ea;padding-top:3px">
       &Delta;m/&Delta;V = <b>${fmt(rSel, 0)} kg/m³</b></div>` + rows;
}

function refresh() { applySize(); applySelection(); updateReadout(); }

function selectCube(n) { selected = n; refresh(); }
function setModel(m) {
  model = m;
  btnUni.classList.toggle('active', m === 'Uniform');
  btnHet.classList.toggle('active', m === 'Heterogeneous');
  refresh();
}
function setSize(v, fromInput) {
  relSize = Math.min(1, Math.max(0.1, v));
  szVal.textContent = relSize.toFixed(2);
  if (!fromInput) szInput.value = String(relSize);
  refresh();
}

[1, 2, 3].forEach(n => btnCube[n].addEventListener('click', () => { stopPlay(); selectCube(n); }));
btnUni.addEventListener('click', () => { stopPlay(); setModel('Uniform'); });
btnHet.addEventListener('click', () => { stopPlay(); setModel('Heterogeneous'); });
szInput.addEventListener('input', () => { stopPlay(); cancelTween(); setSize(parseFloat(szInput.value), true); });

/* ── Guided demo ─────────────────────────────────────────────────────────── */
const steps = [
  {
    title: '1. One bulk density', select: 1, model: 'Uniform', size: 0.5,
    text: 'In a uniform liquid, each dashed cube returns the same Δm/ΔV. One number describes the whole vessel.'
  },
  {
    title: '2. Sample cube 3 near the bottom', select: 3, model: 'Heterogeneous', size: 0.5,
    text: 'Switch the fluid to heterogeneous: the deepest cube now measures a larger mass in the same volume, so (Δm/ΔV)₃ exceeds the others.'
  },
  {
    title: '3. Shrink the sampling volume', select: 3, model: 'Heterogeneous', size: 0.15,
    text: 'Δm and ΔV both collapse toward zero, yet their ratio stabilises — this limiting value is the local density at that point.'
  },
  {
    title: '4. Compare all three points', select: 2, model: 'Heterogeneous', size: 0.5,
    text: 'Back at full size, the three subscripted ratios are distinct numbers tied to three positions: density is defined point by point, not for the container as a whole.'
  }
];
let stepIdx = 0, tweenId = null, playTimer = null;

function cancelTween() { if (tweenId) { cancelAnimationFrame(tweenId); tweenId = null; } }

function tweenSize(target, ms) {
  cancelTween();
  const from = relSize, t0 = performance.now();
  (function run(now) {
    const k = Math.min(1, ((now || t0) - t0) / ms);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    setSize(from + (target - from) * e);
    if (k < 1) tweenId = requestAnimationFrame(run); else tweenId = null;
  })(t0);
}

function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  setModel(s.model);
  selectCube(s.select);
  tweenSize(s.size, 700);
  narration.innerHTML = `<b>${s.title}</b><br>${s.text}`;
}

document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 3600);
});

/* ── Init ────────────────────────────────────────────────────────────────── */
setSize(0.5);
setModel('Uniform');
selectCube(1);
narration.innerHTML = `<b>${steps[0].title}</b><br>${steps[0].text}`;
