/* ── Curved arrows (cubic Bézier tube + cone head, drawn over everything) ── */
function curvedArrow(p0, c1, c2, p3) {
  const V = a => new THREE.Vector3(a[0], a[1], a[2]);
  const curve = new THREE.CubicBezierCurve3(V(p0), V(c1), V(c2), V(p3));
  const m = new THREE.MeshBasicMaterial({
    color: 0x111111, transparent: true, opacity: 1,
    depthTest: false, depthWrite: false
  });
  const grp = new THREE.Group();
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 80, 0.022, 10, false), m);
  tube.renderOrder = 30;
  grp.add(tube);
  const end = curve.getPoint(1);
  const tan = curve.getTangent(1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.072, 0.22, 20), m);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  head.position.copy(end).addScaledVector(tan, 0.09);
  head.renderOrder = 30;
  grp.add(head);
  grp.renderOrder = 30;
  scene.add(grp);
  return grp;
}

